/*
 * Generated by tools/bindings from the spec schemas (plan task 6.1). Do not edit: regenerate with
 * `cargo run -p pact_janus_bindings -- generate`.
 */

/**
 * The resolved hook configuration the engine receives: hooks keyed by lifecycle point, each entry naming one implementation, what it may change, how long it may take and what its failure means. This is the loader's output, never a file: interpolation is done, script sources are inline, and no member holds a template or a path (ADR 0014). The authored file form is project-config.schema.json. See spec.md §6.
 */
export interface HookConfig {
  /**
   * Configuration document version. 1 is the only value v1 defines; an engine that does not know a version fails the run rather than guessing which members it understands.
   */
  version?: number;
  /**
   * Lifecycle point -> the hooks declared at it, in the order they run. A point with no entry is not a point that does nothing: it is a point at which the engine calls nobody.
   */
  hooks?: {
    [k: string]: HookEntry[];
  };
  [k: string]: unknown;
}

/**
 * One hook at one point. Order within a point is declaration order; each entry sees the changes the entries before it made (spec.md §4.2).
 */
export interface HookEntry {
  /**
   * Identifies this hook in events, in the run's hook report, in errors and in explain output. Unique within its point; a duplicate is hook-config-invalid. A hook that cannot be named in a failure message is a hook nobody can debug (spec.md §6.2).
   */
  name: string;
  run: Run;
  /**
   * The hook's own configuration, handed to it as context.config. Fully interpolated: a component, script, command or endpoint receives values, never templates (ADR 0014). The engine MUST NOT echo these values into events, reports, contracts or logs (spec.md §7.3).
   */
  config?: {
    [k: string]: unknown;
  };
  when?: When;
  /**
   * Dotted paths into the hook context this entry may replace, e.g. 'parts.request.headers'. The engine applies a change only if it is declared here AND permitted at the point (spec.md §3), and rejects an undeclared change naming the path. For a component hook this narrows the handshake declaration and can never widen it. An entry with no 'changes' cannot change anything, which is what makes an observing hook auditable as one.
   */
  changes?: string[];
  /**
   * Per-invocation deadline. Defaults to 5000 at exchange and state points, 30000 at run points. Expiry is a hook failure, treated by 'on-failure'; the engine bounds every invocation in time, so a hung hook cannot hang a verification (spec.md §5.4).
   */
  "timeout-ms"?: number;
  /**
   * What a failed invocation means. Defaults are per point (spec.md §5.2) and are chosen so that the default is never the quiet one: a hook whose failure would make a result misleading fails the exchange.
   */
  "on-failure"?: string;
  /**
   * Whether this hook's 'data' is carried in the verification/hook event and the hook report. Off by default because a hook's scratch is where credentials naturally land; the data still reaches later hooks in the run either way (spec.md §7.3, §10.2).
   */
  "report-data"?: boolean;
  [k: string]: unknown;
}

/**
 * The implementation that answers this hook. Exactly one kind; the four kinds are four ways of carrying the same two documents — a context in, a result out (spec.md §8).
 */
export interface Run {
  /**
   * Which implementation. 'script' is the only kind available in every embedding, because the interpreter compiles with the engine (ADR 0015); the others depend on what the embedding can do and are refused by name when it cannot (spec.md §8.5).
   */
  kind: string;
  /**
   * kind 'component': the name of a declared component implementing the hook interface (design 2.6 §8). The component is invoked through hook/invoke with this context and answers with this result.
   */
  component?: string;
  /**
   * kind 'script': the script's source text, inline. A path is a file the engine would have to read, and the engine reads no files (ADR 0014); the loader reads it, transpiles it if it was TypeScript, and puts the result here.
   */
  source?: string;
  /**
   * kind 'script': the function the runtime calls, default 'hook'. One script may serve several points and branch on context.point (spec.md §9.2).
   */
  entry?: string;
  /**
   * kind 'exec': the executable to spawn. Spawned per invocation, handed the context on stdin, answering with a result on stdout (spec.md §8.3).
   */
  command?: string;
  /**
   * kind 'exec': arguments, passed as given. Not a shell string: an argument vector cannot be re-parsed by a shell that quotes differently than the author expected.
   */
  args?: string[];
  /**
   * kind 'exec': working directory for the spawned process.
   */
  cwd?: string;
  /**
   * kind 'exec': the environment the child gets, in full. Deny-by-default like a component's grants (ADR 0013): the child inherits nothing that is not listed here, so a hook cannot pick up an ambient credential the configuration does not show.
   */
  env?: {
    [k: string]: string;
  };
  /**
   * kind 'http': the endpoint the context is POSTed to. This is today's provider-state endpoint, generalised to every point (spec.md §8.4).
   */
  url?: string;
  /**
   * kind 'http': request method, default POST.
   */
  method?: string;
  /**
   * kind 'http': headers sent with the request, values already interpolated — this is where an Authorization header for a state endpoint lives.
   */
  headers?: {
    [k: string]: string;
  };
  /**
   * kind 'http': the body shape. 'janus' is this specification's context document. 'pact-state-change' is the v3/v4 provider-state body ({ state, params, action }) so an existing state-change endpoint keeps working unchanged — the migration case B5 exists for; 'pact-state-change-query' sends the same as query parameters and no body, as today's --state-change-as-query does; 'pact-message', at produce-message, is today's request for a message, and the reply is read as the message (spec.md §8.4).
   */
  format?: string;
  /**
   * kind 'http', format 'pact-message': today's --transports, each a name and the URL it stands for. A message goes to the one named by the transport its pact names, else to the first named 'message' or 'async-message' ('sync-message' for a synchronous message), else to 'url' (spec.md §8.4).
   */
  transports?: {
    name: string;
    url: string;
    [k: string]: unknown;
  }[];
  /**
   * kind 'http': the HTTP client options the endpoint is reached with, the document a provider's transport takes as 'client' (component-interfaces spec §5.6). Its 'retries' defaults to 2 at state-setup and state-teardown and 0 elsewhere, and 'timeout-ms' bounds each attempt (spec.md §8.4, ADR 0044).
   */
  client?: {
    [k: string]: unknown;
  };
  [k: string]: unknown;
}

/**
 * Which occurrences of the point this hook runs at. Members are exact string matches, AND-ed; an absent member matches everything. Deliberately not an expression language — the same refusal variant semantics §3.5 makes for exclusions, for the same reason: a selector that has to be evaluated to be understood cannot be reviewed (spec.md §6.3).
 */
export interface When {
  /**
   * The interaction's description. With states, this is an interaction's identity (contract spec §4.2).
   */
  interaction?: string;
  /**
   * A provider state's name. At state points this selects which state the hook handles; elsewhere it selects interactions carrying that state.
   */
  state?: string;
  /**
   * The interaction's transport kind, e.g. 'http', 'message'. Open vocabulary owned by the transport components (design 2.6).
   */
  transport?: string;
  [k: string]: unknown;
}

/**
 * What the engine hands a hook, at every point and through every implementation. One document, four implementations: a component receives it as hook/invoke's 'context' (design 2.6 §8), a script as its argument, a command on stdin, an endpoint as a POST body — so a hook rewritten from one implementation to another sees the same thing. Which members are present, and which of them may be changed, is fixed per point by spec.md §3; 'mutable' says so in the document itself, so a hook can be written against what it was given rather than against a table.
 */
export interface HookContext {
  /**
   * The lifecycle point this invocation is for. Open vocabulary: an engine that grows a point does not break a hook that does not know it, and a hook that receives a point it does not know answers 'skipped' rather than guessing (spec.md §12.2).
   */
  point: string;
  /**
   * Which side of the contract this run is. Most points exist only on the provider side, because hooks are where the engine drives user code and on the consumer side the user drives the engine (spec.md §2.4).
   */
  role: string;
  run?: RunContext;
  interaction?: InteractionContext;
  variant?: VariantContext;
  state?: StateContext;
  exchange?: ExchangeContext;
  /**
   * The interaction parts in play: design 2.6's Parts document, unchanged and deliberately not restated here — part name -> slot name -> wrapped slot value. Empty at 'produce-message', where producing them is the hook's job.
   */
  parts?: {
    [k: string]: unknown;
  };
  /**
   * Where the exchange is going or came from: design 2.6's EndpointDescriptor, an open document that is never assumed to be a URL.
   */
  endpoint?: {
    [k: string]: unknown;
  };
  /**
   * Present at 'after-verification': the run summary the terminal verification event carries (protocol spec §9.6). Handed to the hook so that a reporting hook reads the same document the host does.
   */
  summary?: {
    [k: string]: unknown;
  };
  /**
   * This hook entry's own configuration, fully interpolated. A hook receives values, never templates (ADR 0014), and the engine never echoes them back out (spec.md §7.3).
   */
  config?: {
    [k: string]: unknown;
  };
  /**
   * The dotted context paths this invocation may replace — the intersection of what the point permits and what the entry declared. A change outside it is refused naming the path, so 'declared' and 'applied' cannot drift apart (spec.md §4.3).
   */
  mutable?: string[];
  /**
   * How long this invocation has. Carried so a hook that talks to something slow can choose its own timeout inside the engine's, rather than being killed mid-call.
   */
  "deadline-ms"?: number;
  [k: string]: unknown;
}

/**
 * The run this invocation belongs to. Present at every point.
 */
export interface RunContext {
  /**
   * Engine-assigned, unique within the life of the pipe; the session id of protocol spec §7.
   */
  id?: string;
  consumer?: {
    name?: string;
    [k: string]: unknown;
  };
  provider?: {
    name?: string;
    [k: string]: unknown;
  };
  /**
   * Hook name -> the 'data' that hook returned earlier in this run, from run-scope points only. This is how a token fetched once at 'before-verification' reaches every 'before-request' without being fetched again, and it is deliberately keyed by hook name: a scratchpad whose entries are anonymous is a scratchpad nobody can attribute.
   */
  data?: {
    [k: string]: unknown;
  };
  [k: string]: unknown;
}

/**
 * The interaction being exercised. Absent at run points.
 */
export interface InteractionContext {
  description?: string;
  /**
   * The interaction's provider states with their parameters already resolved for this variant (variant semantics §6.4) — design 2.5's state records, not restated here.
   */
  states?: {
    [k: string]: unknown;
  }[];
  /**
   * The interaction's transport descriptor: 'kind' and 'mode' (passive or emissive), plus whatever the transport component put there (contract spec §4.3).
   */
  transport?: {
    [k: string]: unknown;
  };
  /**
   * A v1-v4 message interaction's: what today's verifier sends to ask a provider for the message ('request': its description, its providerStates, and a synchronous message's request), whether it is 'synchronous', and the 'transport' the pact names for it, if any. What the 'http' hook's 'pact-message' format sends and routes by (spec.md §3.4, §8.4; staged plan S1.7).
   */
  "pact-message"?: {
    request?: {
      [k: string]: unknown;
    };
    synchronous?: boolean;
    transport?: string;
    [k: string]: unknown;
  };
  [k: string]: unknown;
}

/**
 * Which variant this exchange is for. Absent at run points.
 */
export interface VariantContext {
  /**
   * The variant id, stable and recorded (variant semantics §2.2).
   */
  id?: string;
  /**
   * The variant's assignment as design 2.3 writes it — an array of { dimension, point }, unchanged and not restated here. A hook that must set up data specific to a variant reads the assignment rather than parsing the id, and reads it in the shape the design that owns it uses, because a second shape for the same fact is a second thing to keep in step.
   */
  assignment?: {
    [k: string]: unknown;
  }[];
  [k: string]: unknown;
}

/**
 * Present at 'state-setup' and 'state-teardown': the one state this invocation is for. The engine invokes the point once per state in the interaction's recorded order, so a handler is never handed a list to loop over.
 */
export interface StateContext {
  name?: string;
  /**
   * The state's parameters with variant bindings resolved (variant semantics §6.4). A parameter with no matching case and no default is absent, not null.
   */
  params?: {
    [k: string]: unknown;
  };
  [k: string]: unknown;
}

/**
 * The interaction-and-variant attempt in flight — the unit a verification result reports on (protocol spec §9.6).
 */
export interface ExchangeContext {
  /**
   * Identifies this attempt in events and in the hook report.
   */
  id?: string;
  /**
   * Hook name -> 'data' returned by an earlier hook in this exchange. Cleared when the exchange ends, so nothing leaks into the next variant by accident.
   */
  data?: {
    [k: string]: unknown;
  };
  /**
   * Present at 'state-teardown': how the exchange went, so teardown can differ after a failure. Open vocabulary; 'state-unavailable' is variant semantics §6.7's status and not a synonym for failure.
   */
  outcome?: string;
  [k: string]: unknown;
}

/**
 * What a run records about its hooks: one entry per invocation, in the order they ran, plus the abort reason when a hook ended the run. This document is the answer to 'which hook rewrote this header' — the question that makes a hook chain debuggable or not — and it is why an entry carries the paths a hook changed rather than the values it wrote (spec.md §10). It rides in the run summary; the same entry shape is the payload of the verification/hook event.
 */
export interface HookReport {
  /**
   * Every invocation the run made, including the ones that changed nothing. A hook that ran and did nothing and a hook that never ran are different facts, and only one of them means the selector is wrong.
   */
  invocations?: HookInvocation[];
  aborted?: HookAbort;
  [k: string]: unknown;
}

export interface HookInvocation {
  /**
   * The lifecycle point. Open vocabulary (hook-context.schema.json).
   */
  point: string;
  /**
   * The configured hook's name — the same name the configuration file shows, which is what lets a reader move from this line to the entry that produced it.
   */
  hook: string;
  /**
   * Which kind answered. Recorded because the same hook can be moved between implementations and a report that hides the move hides the cause of the change.
   */
  implementation?: string;
  /**
   * What the hook answered, or what the engine concluded on its behalf when it did not answer at all. 'unsupported' is only meaningful at state points, where it means the provider cannot reach the state (variant semantics §6.7); 'timed-out', 'errored' and 'skipped' are distinct because they send a reader to three different places.
   */
  outcome: string;
  /**
   * The exchange this invocation belonged to; absent at run points.
   */
  exchange?: string;
  /**
   * The interaction's description; absent at run points.
   */
  interaction?: string;
  /**
   * The variant id; absent at run points.
   */
  variant?: string;
  /**
   * The provider state's name; present at state points.
   */
  state?: string;
  /**
   * The context paths this invocation actually replaced — names, never values. Values would put a signed header, a token or a body into every log that carries a summary; the path is what a reader needs and the value is what an attacker needs.
   */
  changed?: string[];
  "duration-ms"?: number;
  /**
   * The hook's own output, present only when its entry set 'report-data' (spec.md §7.3).
   */
  data?: {
    [k: string]: unknown;
  };
  /**
   * The provider-state values a state-setup hook returned (spec.md §3.2), present only when its entry set 'report-data' (spec.md §7.3).
   */
  values?: {
    [k: string]: unknown;
  };
  /**
   * What the outcome did to the run, after 'on-failure' was applied. Present when the outcome was not 'ok', so that a warning that was configured to be a warning is distinguishable from one that was silently treated as such.
   */
  effect?: string;
  /**
   * Why it failed: the protocol's error shape (code, category, message, details, chain). For a component hook this is the component's own error, passed through verbatim — the kernel does not translate component error interiors (protocol spec §10.2).
   */
  error?: {
    [k: string]: unknown;
  };
  [k: string]: unknown;
}

/**
 * Present when a hook ended the run. A run that aborted still reports: the terminal event carries the summary with this member, because a verification that stopped early and a verification that failed are different results and a host that cannot tell them apart will publish one as the other.
 */
export interface HookAbort {
  point: string;
  hook: string;
  /**
   * The failure that aborted the run.
   */
  error?: {
    [k: string]: unknown;
  };
  /**
   * How many interaction-and-variant exchanges never ran because of the abort. Reported as a count of things not done, never folded into the passed or failed tallies.
   */
  "exchanges-not-run"?: number;
  [k: string]: unknown;
}

/**
 * The file a project writes — 'verifier.janus.yaml' on the provider side, 'consumer.janus.yaml' on the consumer side, the same document either way. It is a loader-side artifact: the loader interpolates its '${VAR}' references, reads the files it names and hands the engine a resolved HookConfig (ADR 0014). The difference between this schema and hook-config.schema.json is exactly the work the loader does, which is why the two are separate documents rather than one with optional members. See spec.md §6 and §7.
 */
export interface ProjectConfig {
  /**
   * Configuration document version; 1 in this specification.
   */
  version?: number;
  /**
   * The components this project declares. Governed by design 2.6's ComponentConfig and deliberately not restated here — one member, one owner. Components and hooks share a file because they answer the same question ('what does this project load, and what may it do'), and splitting them would put a component's grants on a different page from the hook that needs them.
   */
  components?: {
    [k: string]: unknown;
  }[];
  /**
   * Lifecycle point -> the hooks declared at it, in the order they run.
   */
  hooks?: {
    [k: string]: AuthoredHook[];
  };
  [k: string]: unknown;
}

/**
 * A hook as written. Every string member may carry '${VAR}' references, which the loader replaces with environment values before the engine sees them; an unset variable fails the run at load, naming it, and never becomes an empty string (spec.md §7.2).
 */
export interface AuthoredHook {
  name: string;
  run: AuthoredRun;
  /**
   * The hook's own configuration, before interpolation. This is where '${JANUS_SIGNING_SECRET}' is written — the secret's name lives in the repository, its value never does.
   */
  config?: {
    [k: string]: unknown;
  };
  /**
   * Selector; the When of hook-config.schema.json, unchanged by resolution.
   */
  when?: {
    [k: string]: unknown;
  };
  /**
   * Dotted context paths this hook may replace.
   */
  changes?: string[];
  "timeout-ms"?: number;
  "on-failure"?: string;
  "report-data"?: boolean;
  [k: string]: unknown;
}

/**
 * As written: the same kinds as the resolved Run, plus the one member resolution removes — 'path', a script file the loader reads and inlines.
 */
export interface AuthoredRun {
  kind: string;
  component?: string;
  /**
   * kind 'script': the script file, relative to the configuration file. The loader reads it, transpiles it when it is TypeScript (spec.md §9.6) and passes the result as 'source'; the engine never sees a path, because an engine that resolves paths is an engine whose runs depend on the directory it was started in.
   */
  path?: string;
  /**
   * kind 'script': the script inline, for a hook short enough to read in the configuration. Exactly one of 'path' and 'source' is present.
   */
  source?: string;
  entry?: string;
  command?: string;
  args?: string[];
  cwd?: string;
  /**
   * The environment the spawned child gets, in full — typically written as '${...}' references, which is how a credential reaches a state handler without being written down.
   */
  env?: {
    [k: string]: string;
  };
  url?: string;
  method?: string;
  headers?: {
    [k: string]: string;
  };
  format?: string;
  transports?: {
    name: string;
    url: string;
    [k: string]: unknown;
  }[];
  client?: {
    [k: string]: unknown;
  };
  [k: string]: unknown;
}
